import re,os,glob
root='AlgebraicJacobian.lean'
mods={}
for f in glob.glob('AlgebraicJacobian/**/*.lean',recursive=True):
    m='AlgebraicJacobian.'+f[len('AlgebraicJacobian/'):-5].replace('/','.')
    mods[m]=f
def imports(path):
    out=[]
    for l in open(path,errors='replace'):
        mm=re.match(r'import\s+(\S+)',l)
        if mm: out.append(mm.group(1))
        elif l.strip() and not l.startswith('--') and not l.startswith('/-'): 
            pass
    return out
seen=set()
stack=[m for m in imports(root) if m in mods]
while stack:
    m=stack.pop()
    if m in seen: continue
    seen.add(m)
    for i in imports(mods[m]):
        if i in mods and i not in seen: stack.append(i)
print('on disk',len(mods),'rooted',len(seen),'unrooted',len(mods)-len(seen))
unr=sorted(set(mods)-seen)
hw=[m for m in unr if 'HighWindow' in m or 'Pointwise' in m]
print('unrooted HighWindow/Pointwise:',len(hw))
for m in hw: print('  ',m)
for t in ['AlgebraicJacobian.Picard.DivSchemeHighWindowPointwiseGenerator','AlgebraicJacobian.Picard.DivRepChartClassUniv','AlgebraicJacobian.Picard.JacobianDataAbelSquare','AlgebraicJacobian.Picard.DivisorFamilyAffGlueZar']:
    print(t.split('.')[-1],'rooted' if t in seen else ('UNROOTED' if t in mods else 'ABSENT'))
